// ---- authentic movement ($MM::Authentic) -----------------------------------
// A Starsiege herc turns; it does not sidestep. hercPos() has no lateral term
// at all, while the shipped values give every chassis a full reverse-speed
// strafe -- the single biggest reason these read as tribesmen rather than as
// walking vehicles. Acceleration comes from the mined per-chassis maxPosAcc.
//
// Both knobs are read at mission load, so serverPrefs can tune them without
// regenerating: StrafeSpeed puts a little sidestep back, AccelScale trims or
// restores the pickup.
if ($MM::StrafeSpeed == "") $MM::StrafeSpeed = 0;
if ($MM::AccelScale == "") $MM::AccelScale = 1.0;
// maxTurnRate / maxTurnRateFast are the hercRot() pair in deg/s, clamped in
// Player::integrateMoveRotation. They are UNPACKED, so the server reads them
// here and the client is fed the same numbers via $MMC::turnSlow/turnFast
// (MechMayhem::pushTurnCap). 0 leaves a body uncapped, which is every
// non-mech armor including the ejected pilot.
if ($MM::TurnScale == "") $MM::TurnScale = 1.0;
if ($MM::Authentic == 1) {
   HercCabasl.maxSideSpeed = $MM::StrafeSpeed;
   HercCabaslDown.maxSideSpeed = $MM::StrafeSpeed;
   HercCabaslCrip.maxSideSpeed = $MM::StrafeSpeed;
   HercCabasl.groundForce = 560.0 * $MM::AccelScale;
   HercCabaslCrip.groundForce = 560.0 * $MM::AccelScale;
   HercCabasl.maxTurnRate = 75.0 * $MM::TurnScale;
   HercCabasl.maxTurnRateFast = 30.0 * $MM::TurnScale;
   HercCabaslCrip.maxTurnRate = 75.0 * $MM::TurnScale;
   HercCabaslCrip.maxTurnRateFast = 30.0 * $MM::TurnScale;
   HercCinapoc.maxSideSpeed = $MM::StrafeSpeed;
   HercCinapocDown.maxSideSpeed = $MM::StrafeSpeed;
   HercCinapocCrip.maxSideSpeed = $MM::StrafeSpeed;
   HercCinapoc.groundForce = 700.0 * $MM::AccelScale;
   HercCinapocCrip.groundForce = 700.0 * $MM::AccelScale;
   HercCinapoc.maxTurnRate = 75.0 * $MM::TurnScale;
   HercCinapoc.maxTurnRateFast = 30.0 * $MM::TurnScale;
   HercCinapocCrip.maxTurnRate = 75.0 * $MM::TurnScale;
   HercCinapocCrip.maxTurnRateFast = 30.0 * $MM::TurnScale;
   HercCinbasl.maxSideSpeed = $MM::StrafeSpeed;
